use std::fs;
use std::io::Read;
use std::path::Path;

fn main() {
    let input_path = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-xadi91gl/data/input.log";
    let cache_path = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-xadi91gl/cache/result.txt";

    // Read as bytes and convert lossily so invalid UTF-8 doesn't cause a failure.
    let mut bytes = Vec::new();
    match fs::File::open(input_path) {
        Ok(mut f) => {
            if let Err(e) = f.read_to_end(&mut bytes) {
                eprintln!("Failed to read {}: {}", input_path, e);
                std::process::exit(1);
            }
        }
        Err(e) => {
            eprintln!("Failed to open {}: {}", input_path, e);
            std::process::exit(1);
        }
    }

    let content = String::from_utf8_lossy(&bytes);
    let count = content.lines().filter(|line| line.contains("ERROR")).count();

    println!("{}", count);

    // Cache the result for the CI dashboard (per docs/CONTRIBUTING.md).
    if let Some(parent) = Path::new(cache_path).parent() {
        if let Err(e) = fs::create_dir_all(parent) {
            eprintln!("Failed to create cache directory {}: {}", parent.display(), e);
            std::process::exit(1);
        }
    }
    if let Err(e) = fs::write(cache_path, format!("{}\n", count)) {
        eprintln!("Failed to write cache file {}: {}", cache_path, e);
        std::process::exit(1);
    }
}

