use std::fs::File;
use std::io::{BufRead, BufReader, Read};
use std::path::Path;

const INPUT_PATH: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-mawr8soh/data/input.log";
const OVERRIDES_PATH: &str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-mawr8soh/etc/overrides.conf";

fn load_needle() -> String {
    let mut needle = String::from("ERROR");
    let path = Path::new(OVERRIDES_PATH);
    if path.exists() {
        if let Ok(mut f) = File::open(path) {
            let mut bytes = Vec::new();
            if f.read_to_end(&mut bytes).is_ok() {
                let content = String::from_utf8_lossy(&bytes);
                for line in content.lines() {
                    let line = line.trim_end_matches('\r');
                    if let Some(rest) = line.strip_prefix("needle=") {
                        // Ignore empty needles (would match every line).
                        if !rest.is_empty() {
                            needle = rest.to_string();
                        }
                    }
                }
            }
        }
    }
    needle
}

fn main() {
    let needle = load_needle();

    let file = match File::open(INPUT_PATH) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("error: cannot open {}: {}", INPUT_PATH, e);
            std::process::exit(1);
        }
    };

    let mut reader = BufReader::new(file);
    let mut buf: Vec<u8> = Vec::new();
    let mut count: u64 = 0;

    loop {
        buf.clear();
        match reader.read_until(b'\n', &mut buf) {
            Ok(0) => break,
            Ok(_) => {
                let line = String::from_utf8_lossy(&buf);
                if line.contains(needle.as_str()) {
                    count += 1;
                }
            }
            Err(e) => {
                eprintln!("error: failed reading {}: {}", INPUT_PATH, e);
                std::process::exit(1);
            }
        }
    }

    println!("{}", count);
}

