fn slurp[&f, &o](fs: &f Fs("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-52mkeomc/data/input.log"), out: &!o [byte]) -> [fs_read("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-52mkeomc/data/input.log")] int {
    return fs_read(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-52mkeomc/data/input.log", out);
}

fn save[&f, &b](fs: &f Fs("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-52mkeomc/cache/result.txt"), data: &b [byte]) -> [fs_write("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-52mkeomc/cache/result.txt")] int {
    return fs_write(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-52mkeomc/cache/result.txt", data);
}

fn say[&i, &b](io: &!i Io, data: &b [byte]) -> [io_write] int {
    return io.write_all(io, data);
}

// Count lines containing "ERROR" in the first n bytes.
fn tally[&r](data: &r [byte], n: int) -> [] int {
    var i = 0;
    var count = 0;
    var hit = 0;
    while i < n {
        let c = int_of(data[i]);
        if c == 10 {
            if hit == 1 {
                count = count + 1;
            }
            hit = 0;
        } else if i + 5 <= n && c == 69 && int_of(data[i + 1]) == 82 && int_of(data[i + 2]) == 82 && int_of(data[i + 3]) == 79 && int_of(data[i + 4]) == 82 {
            hit = 1;
        }
        i = i + 1;
    }
    if hit == 1 {
        count = count + 1;
    }
    return count;
}

fn main(world: World) -> [] int {
    let Split { io, ffi, fs, heap, args } = split(world);
    release(ffi);
    release(args);
    let (inp, outp) = narrow(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-52mkeomc/data/input.log", "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-52mkeomc/cache/result.txt");
    borrow mut heap as &!h in {
        borrow mut io as &!i in {
            let data = box_slice(h, 1048576, byte_of(0));
            var n = 0;
            borrow mut data as &!w in {
                borrow inp as &f in {
                    n = slurp(f, contents(w));
                }
            }
            var count = 0;
            borrow data as &r in {
                count = tally(contents(r), n);
            }
            unbox_slice(h, data);

            var text = buffer.empty(h, 32);
            text = buffer.push_nat(h, text, count);
            text = buffer.push(h, text, byte_of(10));
            borrow text as &t in {
                say(i, buffer.bytes(t));
                borrow outp as &x in {
                    save(x, buffer.bytes(t));
                }
            }
            buffer.drop(h, text);
        }
    }
    release(inp);
    release(outp);
    release(heap);
    release(io);
    return 0;
}

