    if i + 5 > n {
        return false;
    }
    return int_of(s[i]) == 69
        && int_of(s[i + 1]) == 82
        && int_of(s[i + 2]) == 82
        && int_of(s[i + 3]) == 79
        && int_of(s[i + 4]) == 82;
