use std::fs;
use std::io::Read;
use std::path::Path;

fn count_in_file(path: &Path) -> usize {
    let mut file = match fs::File::open(path) {
        Ok(f) => f,
        Err(_) => return 0,
    };
    let mut bytes = Vec::new();
    if file.read_to_end(&mut bytes).is_err() {
        return 0;
    }
    let text = String::from_utf8_lossy(&bytes);
    text.lines().filter(|line| line.contains("ERROR")).count()
}

fn walk(dir: &Path, total: &mut usize) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let file_type = match entry.file_type() {
            Ok(t) => t,
            Err(_) => continue,
        };
        // Do not follow symlinks to avoid cycles.
        if file_type.is_symlink() {
            continue;
        }
        if file_type.is_dir() {
            walk(&path, total);
        } else if file_type.is_file() {
            *total += count_in_file(&path);
        }
    }
}

fn main() {
    let root = Path::new("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-fl1h0lg6");
    let mut total = 0usize;
    if root.is_file() {
        total += count_in_file(root);
    } else {
        walk(root, &mut total);
    }
    println!("{}", total);
}

