fn count_errors[&r](text: &r [byte]) -> [] int {
    let n = len(text);
    var i = 0;
    var total = 0;
    var line_hit = false;
    while i < n {
        let c = int_of(text[i]);
        if c == 10 {
            if line_hit { total = total + 1; }
            line_hit = false;
        } else if i + 5 <= n
            && c == 69
            && int_of(text[i + 1]) == 82
            && int_of(text[i + 2]) == 82
            && int_of(text[i + 3]) == 79
            && int_of(text[i + 4]) == 82 {
            line_hit = true;
        }
        i = i + 1;
    }
    if line_hit { total = total + 1; }
    return total;
}

fn scan[&h, &f](heap: &!h Heap, fs: &f Fs("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-2qenit1h"), path: &static [byte]) -> [heap, fs_read("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-2qenit1h")] int {
    let store = box_slice(heap, 1048576, byte_of(0));
    var total = 0;
    borrow mut store as &!w in {
        let got = fs_read(fs, path, contents(w));
        if got > 0 {
            total = count_errors(contents(w)[0..got]);
        }
    }
    unbox_slice(heap, store);
    return total;
}

