def count_error_lines(root: str) -> int:
    total: int = 0
    for dirpath, dirnames, filenames in os.walk(root):
        for name in filenames:
            path: str = os.path.join(dirpath, name)
            # Skip symlinks to avoid double counting or escaping the project
            if os.path.islink(path):
                continue
            try:
                with open(path, "r", encoding="utf-8", errors="replace") as f:
                    for line in f:
                        if "ERROR" in line:
                            total += 1
            except (OSError, UnicodeError):
                # Unreadable file (permissions, special file, etc.) - skip it
                continue
    return total


