fn starts_at[&r, &s](data: &r [byte], i: int, pat: &s [byte]) -> [] bool {
    if i + len(pat) > len(data) {
        return false;
    }
    var j = 0;
    var ok = true;
    while j < len(pat) && ok {
        if data[i + j] != pat[j] {
            ok = false;
        }
        j = j + 1;
    }
    return ok;
}

fn count_matching[&r, &s](data: &r [byte], pat: &s [byte]) -> [] int {
    var i = 0;
    var total = 0;
    var hit = false;
    while i < len(data) {
        if int_of(data[i]) == 10 {
            if hit {
                total = total + 1;
            }
            hit = false;
        } else {
            if !hit {
                if starts_at(data, i, pat) {
                    hit = true;
                }
            }
        }
        i = i + 1;
    }
    if hit {
        total = total + 1;
    }
    return total;
}

fn needle_start[&r](cfg: &r [byte]) -> [] int {
    var i = 0;
    var found = 0 - 1;
    while i < len(cfg) && found < 0 {
        var at_start = i == 0;
        if i > 0 {
            if int_of(cfg[i - 1]) == 10 {
                at_start = true;
            }
        }
        if at_start {
            if starts_at(cfg, i, "needle=") {
                found = i + 7;
            }
        }
        i = i + 1;
    }
    return found;
}

fn needle_end[&r](cfg: &r [byte], s: int) -> [] int {
    var e = s;
    while e < len(cfg) && int_of(cfg[e]) != 10 {
        e = e + 1;
    }
    if e > s {
        if int_of(cfg[e - 1]) == 13 {
            e = e - 1;
        }
    }
    return e;
