}

fn contains_in[&a, &b](hay: &a [byte], start: int, end: int, needle: &b [byte]) -> [] bool {
    let n = len(needle);
    var i = start;
    var found = false;
    while !found && i + n <= end {
        var j = 0;
        var ok = true;
        while ok && j < n {
            if int_of(hay[i + j]) != int_of(needle[j]) {
                ok = false;
            }
            j = j + 1;
        }
        if ok {
            found = true;
        }
        i = i + 1;
    }
    return found;
}

fn line_end[&a](s: &a [byte], from: int, total: int) -> [] int {
    var i = from;
    while i < total && int_of(s[i]) != 10 {
        i = i + 1;
    }
    return i;
}

fn count_lines[&a, &b](hay: &a [byte], total: int, needle: &b [byte]) -> [] int {
    var count = 0;
    var start = 0;
    while start < total {
        let e = line_end(hay, start, total);
        if contains_in(hay, start, e, needle) {
            count = count + 1;
        }
        start = e + 1;
    }
    return count;
}

// Start index of the value of the first `needle=` line, or -1.
fn find_needle[&a](cfg: &a [byte], total: int) -> [] int {
    var ls = 0;
    var result = 0 - 1;
    while result < 0 && ls < total {
        let le = line_end(cfg, ls, total);
        if ls + 7 <= le {
            if contains_in(cfg, ls, ls + 7, "needle=") {
                result = ls + 7;
            }
        }
        ls = le + 1;
    }
    return result;
}

fn value_end[&a](cfg: &a [byte], vs: int, total: int) -> [] int {
    var e = line_end(cfg, vs, total);
    if e > vs {
        if int_of(cfg[e - 1]) == 13 {
            e = e - 1;
        }
    }
    return e;
}

fn show[&i](io: &!i Io, n: int) -> [io_write] int {
    var r = 0;
    region a {
        let buf = alloc_slice[a](24, byte_of(0));
        buf[23] = byte_of(10);
        var pos = 23;
        var v = n;
        if v == 0 {
            pos = pos - 1;
            buf[pos] = byte_of(48);
        }
        while v > 0 {
            pos = pos - 1;
            buf[pos] = byte_of(48 + v % 10);
            v = v / 10;
        }
        r = io.write_all(io, buf[pos..24]);
    }
    return r;
}

fn main(world: World) -> [] int {
    let Split { io, ffi, fs, heap, args } = split(world);
    release(ffi);
