    var status = 1;
    var count = 0;
    borrow mut heap as &!h in {
        let ibox = box_slice(h, 8388608, byte_of(0));
        let cbox = box_slice(h, 65536, byte_of(0));
        var got = 0 - 1;
        var cgot = 0 - 1;
        borrow mut ibox as &!iw in {
            borrow inp as &x in {
                got = read_input(x, contents(iw));
            }
        }
        borrow mut cbox as &!cw in {
            borrow cfg as &y in {
                cgot = read_cfg(y, contents(cw));
            }
        }
        if got >= 0 {
            status = 0;
            borrow ibox as &ir in {
                borrow cbox as &cr in {
                    let idata = contents(ir);
                    let cdata = contents(cr);
                    var vs = 0 - 1;
                    var ve = 0;
                    if cgot > 0 {
                        vs = find_needle(cdata, cgot);
                        if vs >= 0 {
                            ve = value_end(cdata, vs, cgot);
                        }
                    }
                    if vs >= 0 && ve > vs {
                        count = count_lines(idata, got, cdata[vs..ve]);
                    } else {
                        count = count_lines(idata, got, "ERROR");
                    }
                }
            }
        }
        unbox_slice(h, ibox);
        unbox_slice(h, cbox);
    }
    release(heap);
    release(inp);
    release(cfg);
    if status == 0 {
        borrow mut io as &!i in {
            show(i, count);
        }
    }
    release(io);
    return status;
}

