                if int_of(s[i + 1]) == 82 && int_of(s[i + 2]) == 82 && int_of(s[i + 3]) == 79 && int_of(s[i + 4]) == 82 {
                    flagged = true;
                }
            }
        }
        i = i + 1;
    }
    if pending && flagged {
