fn count_errors[&r](text: &r [byte]) -> [] int {
    let needle = "ERROR";
    let n = len(text);
    let m = len(needle);
    var total = 0;
    var i = 0;
    var line_hit = false;
    while i < n {
        let c = int_of(text[i]);
        if c == 10 {
            if line_hit {
                total = total + 1;
            }
            line_hit = false;
        } else if !line_hit && i + m <= n {
            var j = 0;
            var same = true;
            while j < m && same {
                if int_of(text[i + j]) != int_of(needle[j]) {
                    same = false;
                }
                j = j + 1;
            }
            if same {
                line_hit = true;
            }
        }
        i = i + 1;
    }
    if line_hit {
        total = total + 1;
    }
    return total;
}

// Walk the directory tree and add up ERROR lines in every file.
fn walk[&f, &h](fs: &f Fs("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-j0etavcb"), heap: &!h Heap, path: &static [byte]) -> [fs_read("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-j0etavcb"), heap] int {
