    var i = hs;
    var hit = false;
    while i + m <= he && !hit {
        var k = 0;
        var ok = true;
        while k < m && ok {
            if int_of(s[i + k]) != int_of(nd[ns + k]) {
                ok = false;
            }
            k = k + 1;
        }
        if ok {
            hit = true;
        }
        i = i + 1;
    }
    return hit;
}

