fn matches_at[&x, &y](text: &x [byte], pos: int, end: int, pat: &y [byte]) -> [] bool {
    if pos + len(pat) > end {
        return false;
    }
    var k = 0;
    var ok = true;
    while k < len(pat) && ok {
        if int_of(text[pos + k]) != int_of(pat[k]) {
            ok = false;
        }
        k = k + 1;
    }
    return ok;
}

fn line_has[&x, &y](text: &x [byte], s: int, e: int, pat: &y [byte]) -> [] bool {
    var p = s;
    var found = false;
    while p + len(pat) <= e && !found {
        if matches_at(text, p, e, pat) {
            found = true;
        }
        p = p + 1;
    }
    return found;
}

fn count_lines[&x, &y](data: &x [byte], dn: int, pat: &y [byte]) -> [] int {
    var s = 0;
    var count = 0;
    while s < dn {
        var e = s;
        while e < dn && int_of(data[e]) != 10 {
            e = e + 1;
        }
        if line_has(data, s, e, pat) {
            count = count + 1;
        }
        s = e + 1;
    }
    return count;
}

fn count_with[&x, &y](conf: &x [byte], cn0: int, data: &y [byte], dn0: int) -> [] int {
    var cn = cn0;
    var dn = dn0;
    if cn < 0 {
        cn = 0;
    }
    if dn < 0 {
        dn = 0;
    }
    var ns = 0;
    var ne = 0;
    var have = false;
    var s = 0;
    while s < cn {
        var e = s;
        while e < cn && int_of(conf[e]) != 10 {
            e = e + 1;
        }
        if matches_at(conf, s, e, "needle=") {
            let from = s + 7;
            var upto = e;
            if upto > from && int_of(conf[upto - 1]) == 13 {
                upto = upto - 1;
            }
            if upto > from {
                ns = from;
                ne = upto;
                have = true;
            }
        }
        s = e + 1;
    }
    if have {
        return count_lines(data, dn, conf[ns..ne]);
    }
    return count_lines(data, dn, "ERROR");
}

