"""Count lines in a log file that contain a given needle (default: ERROR).

An optional overrides file may contain a line `needle=TEXT` which replaces
the default needle.
"""

import os
import sys

BASE_DIR = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-1u9yfum7"
INPUT_PATH = os.path.join(BASE_DIR, "data", "input.log")
