DEFAULT_NEEDLE = "ERROR"


def load_needle(path: str) -> str:
    """Return the needle from the overrides file if present, else the default."""
    needle = DEFAULT_NEEDLE
    if not os.path.isfile(path):
        return needle
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            for raw in f:
                line = raw.rstrip("\r\n")
                if line.startswith("needle="):
                    value = line[len("needle="):]
                    # Ignore an empty override; an empty needle would match every line.
                    if value:
                        needle = value
    except OSError as exc:
        print(f"Warning: could not read overrides file: {exc}", file=sys.stderr)
    return needle


def count_matching_lines(path: str, needle: str) -> int:
    count = 0
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for line in f:
            if needle in line:
                count += 1
    return count


def main() -> int:
    needle = load_needle(OVERRIDES_PATH)
    try:
        total = count_matching_lines(INPUT_PATH, needle)
    except OSError as exc:
        print(f"Error: could not read input file: {exc}", file=sys.stderr)
        return 1
    print(total)
    return 0


if __name__ == "__main__":
    sys.exit(main())

