    let root = Path::new("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-n8kfk14a");
    let mut total = 0usize;
    if root.is_file() {
        total += count_in_file(root);
    } else {
        walk(root, &mut total);
    }
    println!("{}", total);
}

