fn read_input[&f, &o](fs: &f Fs("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-0bekj64g/data/input.log"), out: &!o [byte]) -> [fs_read("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-0bekj64g/data/input.log")] int {
