}

fn matches_at[&r, &p](text: &r [byte], i: int, pat: &p [byte]) -> [] bool {
    var j = 0;
    var ok = true;
    while j < len(pat) && ok {
        if text[i + j] != pat[j] {
            ok = false;
        }
        j = j + 1;
    }
    return ok;
}

fn line_has[&r, &p](text: &r [byte], start: int, end: int, needle: &p [byte]) -> [] bool {
    var i = start;
    var found = false;
    while i + len(needle) <= end && !found {
        if matches_at(text, i, needle) {
            found = true;
        }
        i = i + 1;
    }
    return found;
}

fn count_lines[&r, &p](text: &r [byte], n: int, needle: &p [byte]) -> [] int {
    var count = 0;
    var start = 0;
    var i = 0;
    while i <= n {
        var brk = i == n;
        if i < n {
            if int_of(text[i]) == 10 {
                brk = true;
            }
        }
        if brk {
            if line_has(text, start, i, needle) {
                count = count + 1;
            }
            start = i + 1;
        }
        i = i + 1;
    }
    return count;
}

// Index just after "needle=" on the first line that starts with it, or -1.
fn needle_start[&r](cfg: &r [byte], n: int) -> [] int {
    var i = 0;
    var found = 0 - 1;
    while i < n && found < 0 {
        var hit = false;
        if i + 7 <= n {
            if matches_at(cfg, i, "needle=") {
                hit = true;
            }
        }
        if hit {
            found = i + 7;
        } else {
            var skipping = true;
            while skipping {
                if i >= n {
                    skipping = false;
                } else if int_of(cfg[i]) == 10 {
                    skipping = false;
                } else {
                    i = i + 1;
                }
            }
            i = i + 1;
        }
    }
    return found;
}

fn value_end[&r](cfg: &r [byte], n: int, a: int) -> [] int {
    var e = a;
    var going = true;
    while going {
        if e >= n {
            going = false;
        } else if int_of(cfg[e]) == 10 {
            going = false;
        } else {
            e = e + 1;
        }
    }
    if e > a {
        if int_of(cfg[e - 1]) == 13 {
            e = e - 1;
        }
    }
    return e;
}

fn run[&h, &a, &c](heap: &!h Heap, input: &a Fs("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-0bekj64g/data/input.log"), cfg: &c Fs("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-0bekj64g/etc/overrides.conf")) -> [heap, fs_read("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-0bekj64g/data/input.log"), fs_read("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-0bekj64g/etc/overrides.conf")] int {
    let big = box_slice(heap, 4194304, byte_of(0));
    let small = box_slice(heap, 65536, byte_of(0));
    var total = 0;
    borrow mut big as &!bw in {
        borrow mut small as &!sw in {
            let text = contents(bw);
            let conf = contents(sw);
            let n = read_input(input, text);
            let m = read_cfg(cfg, conf);
            if n > 0 {
                var s = 0 - 1;
                if m > 0 {
                    s = needle_start(conf, m);
                }
                var used_custom = false;
                if s >= 0 {
                    let e = value_end(conf, m, s);
                    if e > s {
                        total = count_lines(text, n, conf[s..e]);
                        used_custom = true;
                    }
                }
                if !used_custom {
                    total = count_lines(text, n, "ERROR");
                }
            }
        }
    }
    unbox_slice(heap, small);
    unbox_slice(heap, big);
    return total;
}

fn emit[&h, &i](heap: &!h Heap, io: &!i Io, n: int) -> [heap, io_write] int {
    var b = buffer.empty(heap, 32);
    b = buffer.push_nat(heap, b, n);
    b = buffer.push(heap, b, byte_of(10));
    var r = 0;
    borrow b as &t in {
        r = io.write_all(io, buffer.bytes(t));
    }
    buffer.drop(heap, b);
    return r;
}

fn main(world: World) -> [] int {
    let Split { io, ffi, fs, heap, args } = split(world);
    release(ffi);
