    let (inp, cfgc) = narrow(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-0bekj64g/data/input.log", "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-0bekj64g/etc/overrides.conf");
    borrow mut heap as &!h in {
        borrow mut io as &!i in {
            borrow inp as &x in {
                borrow cfgc as &y in {
                    let n = run(h, x, y);
                    emit(h, i, n);
                }
            }
        }
    }
    release(inp);
    release(cfgc);
    release(heap);
    release(io);
    return 0;
}

