fn at_error[&r](data: &r [byte], i: int, n: int) -> [] bool {
    return i + 5 <= n
        && int_of(data[i]) == 69
        && int_of(data[i + 1]) == 82
        && int_of(data[i + 2]) == 82
        && int_of(data[i + 3]) == 79
        && int_of(data[i + 4]) == 82;
}

fn count_errors[&r](data: &r [byte], n: int) -> [] int {
    var i = 0;
    var count = 0;
    var flag = 0;
    while i < n {
        if int_of(data[i]) == 10 {
            if flag == 1 {
                count = count + 1;
            }
            flag = 0;
        } else if at_error(data, i, n) {
            flag = 1;
        }
        i = i + 1;
    }
    if flag == 1 {
        count = count + 1;
    }
    return count;
}

