use std::fs::File;
use std::io::{BufRead, BufReader};

fn main() {
    let path = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-d9mz1a0g/data/input.log";

    let file = match File::open(path) {
