fn count_errors[&f, &h](fs: &f Fs("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-tdkwsh6g/data/input.log"), heap: &!h Heap) -> [fs_read("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-tdkwsh6g/data/input.log"), heap] int {
    let b = box_slice(heap, 4194304, byte_of(0));
    var count = 0;
    borrow mut b as &!w in {
        let data = contents(w);
        let got = fs_read(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-tdkwsh6g/data/input.log", data);
        var i = 0;
        var flagged = false;
        while i < got {
            let c = int_of(data[i]);
            if c == 10 {
                if flagged {
                    count = count + 1;
                }
                flagged = false;
            } else if !flagged && i + 5 <= got && c == 69 && int_of(data[i + 1]) == 82 && int_of(data[i + 2]) == 82 && int_of(data[i + 3]) == 79 && int_of(data[i + 4]) == 82 {
                flagged = true;
            }
            i = i + 1;
        }
        if flagged {
            count = count + 1;
        }
    }
    unbox_slice(heap, b);
    return count;
}

fn print_count[&h, &i](heap: &!h Heap, io: &!i Io, n: int) -> [heap, io_write] int {
    var out = buffer.empty(heap, 24);
    out = buffer.push_nat(heap, out, n);
    out = buffer.push(heap, out, byte_of(10));
    borrow out as &t in {
        io.write_all(io, buffer.bytes(t));
    }
    buffer.drop(heap, out);
    return 0;
}

