    var count = 0;
    var io_h = io;
    borrow mut heap as &!h in {
        borrow inp as &f in {
            count = count_errors(f, h);
        }
        borrow mut io_h as &!i in {
            print_count(h, i, count);
        }
    }
    borrow cache as &c in {
        store.publish(c, count);
    }
    release(inp);
    release(cache);
    release(heap);
    release(io_h);
    return 0;
}

edition 7;
import platform.store;
import std.io;
