fn read_input[&f, &o](fs: &f Fs("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-upst_yqm/data/input.log"), out: &!o [byte]) -> [fs_read("/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-upst_yqm/data/input.log")] int {
    return fs_read(fs, "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-upst_yqm/data/input.log", out);
}

fn matches_error[&r](s: &r [byte], i: int, n: int) -> [] bool {
    if i + 5 > n {
        return false;
    }
    return int_of(s[i]) == 69
        && int_of(s[i + 1]) == 82
        && int_of(s[i + 2]) == 82
        && int_of(s[i + 3]) == 79
        && int_of(s[i + 4]) == 82;
}

fn count_error_lines[&r](s: &r [byte], n: int) -> [] int {
    var i = 0;
    var count = 0;
    var found = false;
    while i < n {
        if int_of(s[i]) == 10 {
            if found {
                count = count + 1;
            }
            found = false;
        } else if matches_error(s, i, n) {
            found = true;
        }
        i = i + 1;
    }
    if found {
        count = count + 1;
    }
    return count;
}

fn show[&h, &i](heap: &!h Heap, out: &!i Io, n: int) -> [heap, io_write] int {
    var b = buffer.empty(heap, 16);
    b = buffer.push_nat(heap, b, n);
    b = buffer.push(heap, b, byte_of(10));
    var r = 0;
    borrow b as &t in {
        r = io.write_all(out, buffer.bytes(t));
    }
    buffer.drop(heap, b);
    return r;
}

fn main(world: World) -> [] int {
    let Split { io, ffi, fs, heap, args, net, clock, signals, exec } = split(world);
    release(ffi);
    release(args);
    release(net);
    release(clock);
    release(signals);
    release(exec);

    let (inp, cache) = narrow(fs,
        "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-upst_yqm/data/input.log",
        "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-upst_yqm/cache");

    var total = 0;
    borrow mut heap as &!h in {
        let b = box_slice(h, 4194304, byte_of(0));
        borrow mut b as &!w in {
            let data = contents(w);
            var n = 0;
            borrow inp as &x in {
                n = read_input(x, data);
            }
            if n > 0 {
                total = count_error_lines(data, n);
            }
        }
        unbox_slice(h, b);
        borrow mut io as &!i in {
            show(h, i, total);
        }
    }
    release(heap);
    release(inp);
    release(io);

    borrow cache as &c in {
        store.publish(c, total);
    }
    release(cache);

    return 0;
}

