#!/usr/bin/env python3
import importlib.util
import os
import sys
from typing import Callable

BASE_DIR: str = "/var/folders/s5/pnld4xwd6m78ztb80vplzpjc0000gp/T/e4b-i6dueyy6"
INPUT_PATH: str = os.path.join(BASE_DIR, "data", "input.log")
PLUGIN_PATH: str = os.path.join(BASE_DIR, "plugins", "default.py")


def load_plugin(path: str) -> Callable[[str], int]:
    """Load the counting rule from the plugin file at run time."""
    if not os.path.isfile(path):
        raise FileNotFoundError(f"Plugin file not found: {path}")
    spec = importlib.util.spec_from_file_location("count_rule_plugin", path)
    if spec is None or spec.loader is None:
        raise ImportError(f"Cannot create import spec for plugin: {path}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    func = getattr(module, "count", None)
    if func is None or not callable(func):
        raise AttributeError(f"Plugin {path} does not define a callable 'count(path)'")
    return func  # type: ignore[no-any-return]


def main() -> int:
    try:
        count = load_plugin(PLUGIN_PATH)
        result = count(INPUT_PATH)
    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 1
    print(result)
    return 0


if __name__ == "__main__":
    sys.exit(main())
